import { useCallback, useRef, useState } from 'react';

export interface QueueAction {
  id: string;
  payload: string;
  status: 'pending' | 'syncing' | 'synced' | 'failed';
}

export interface OfflineQueueState {
  actions: QueueAction[];
  isOnline: boolean;
}

interface EnqueueInput {
  id: string;
  payload: string;
}

export function useOfflineQueue(): OfflineQueueState & {
  enqueue: (input: EnqueueInput) => void;
  retry: (id: string) => void;
} {
  const [actions, setActions] = useState<QueueAction[]>([]);
  const [isOnline, setIsOnline] = useState(true);
  const syncRef = useRef(false);

  const sync = useCallback(async () => {
    if (syncRef.current) return;
    syncRef.current = true;
    try {
      setActions(prev => prev.map(a => (a.status === 'pending' ? { ...a, status: 'syncing' } : a)));
      const pending = actions.filter(a => a.status === 'pending' || a.status === 'failed');
      for (const action of pending) {
        const response = await fetch('https://api.example.com/queue', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ id: action.id, payload: action.payload }),
        });
        if (!response.ok) throw new Error(`Sync failed: ${response.status}`);
        setActions(prev =>
          prev.map(a => (a.id === action.id ? { ...a, status: 'synced' } : a))
        );
      }
    } catch (err) {
      setActions(prev =>
        prev.map(a => (a.status === 'syncing' ? { ...a, status: 'failed' } : a))
      );
      setIsOnline(false);
      void err;
    } finally {
      syncRef.current = false;
    }
  }, [actions]);

  const enqueue = useCallback(
    ({ id, payload }: EnqueueInput) => {
      setActions(prev => [...prev, { id, payload, status: 'pending' }]);
      void sync();
    },
    [sync]
  );

  const retry = useCallback(
    (id: string) => {
      setActions(prev => prev.map(a => (a.id === id ? { ...a, status: 'pending' } : a)));
      setIsOnline(true);
      void sync();
    },
    [sync]
  );

  return { actions, isOnline, enqueue, retry };
}

import { FlatList, Text, View, StyleSheet } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { useOfflineQueue } from '../hooks/useOfflineQueue';

export function QueueScreen(): JSX.Element {
  const { actions, isOnline, enqueue, retry } = useOfflineQueue();
  return (
    <SafeAreaView style={styles.safe}>
      <Text style={styles.banner}>
        {isOnline ? 'Online — syncing in the background' : 'Offline — changes queued'}
      </Text>
      <FlatList
        data={actions}
        keyExtractor={item => item.id}
        renderItem={({ item }) => (
          <View style={styles.row}>
            <Text style={styles.rowText}>
              {item.payload} · {item.status}
            </Text>
            {item.status === 'failed' && (
              <Text style={styles.retry} onPress={() => retry(item.id)} accessibilityRole="button">
                Retry
              </Text>
            )}
          </View>
        )}
        ListEmptyComponent={<Text>No queued actions.</Text>}
      />
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1 },
  banner: { padding: 16, fontWeight: '600' },
  row: { flexDirection: 'row', justifyContent: 'space-between', padding: 16 },
  rowText: { fontSize: 15 },
  retry: { color: '#007AFF', fontWeight: '600' },
});
